select id, report_user_id reportUserId, report_user_name reportUserName, accuse_id accuseId, accuse_type accuseType, accuse_name accuseName, report_status reportStatus, `desc`, reason, ctime, uptime from corgi_report
where report_status = #{status}
order by id desc

select count(1) from corgi_blacklist
where user_id = #{userId}
and black_id = #{blockId}
